export interface Env { DB:D1Database; MEDIA?:R2Bucket; ENVIRONMENT:string; ACCESS_TTL_SECONDS:string; REFRESH_TTL_SECONDS:string; PIN_PEPPER:string; PIN_ITERATIONS?:string; ADMIN_TOKEN?:string; UPCITEMDB_KEY?:string; }
type Json=Record<string,unknown>; type Auth={userId:string;sessionId:string};
class ApiError extends Error { constructor(public status:number,public code:string,message:string){super(message)} }
const json=(body:unknown,status=200)=>new Response(JSON.stringify(body),{status,headers:{'content-type':'application/json','cache-control':'no-store'}});
const now=()=>Math.floor(Date.now()/1000); const id=()=>crypto.randomUUID();
const enc=new TextEncoder();
async function hash(s:string){const b=await crypto.subtle.digest('SHA-256',enc.encode(s));return [...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join('')}
// workerd (Cloudflare Workers runtime) PBKDF2 ko 100000 iterations par cap karta hai; usse upar NotSupportedError/OperationError milta hai.
const PBKDF2_MAX_ITERATIONS=100000;
function pinIterations(env:Env){const n=Math.floor(Number(env.PIN_ITERATIONS));return Number.isFinite(n)&&n>=1000?Math.min(n,PBKDF2_MAX_ITERATIONS):PBKDF2_MAX_ITERATIONS}
function phone(v:unknown){const s=String(v??'').replace(/[\s-]/g,'');if(!/^\+[1-9]\d{7,14}$/.test(s))throw new ApiError(400,'INVALID_PHONE','Use E.164 phone format');return s}
async function body(req:Request):Promise<Json>{try{return await req.json() as Json}catch{throw new ApiError(400,'INVALID_JSON','Expected JSON body')}}
function str(v:unknown,name:string,min=1,max=200){if(typeof v!=='string'||v.trim().length<min||v.trim().length>max)throw new ApiError(400,'VALIDATION_ERROR',`Invalid ${name}`);return v.trim()}
async function bearer(req:Request,env:Env):Promise<Auth>{const h=req.headers.get('authorization');if(!h?.startsWith('Bearer '))throw new ApiError(401,'UNAUTHENTICATED','Authentication required');const token=h.slice(7),tokenHash=await hash(token),t=now();const row=await env.DB.prepare(`SELECT s.id session_id,s.user_id FROM sessions s JOIN users u ON u.id=s.user_id WHERE s.access_hash=? AND s.revoked_at IS NULL AND s.access_expires_at>? AND u.status='ACTIVE'`).bind(tokenHash,t).first<{session_id:string,user_id:string}>();if(!row)throw new ApiError(401,'INVALID_SESSION','Session expired or invalid');env.DB.prepare('UPDATE sessions SET last_used_at=? WHERE id=?').bind(t,row.session_id).run().catch(()=>{});return{userId:row.user_id,sessionId:row.session_id}}
async function membership(env:Env,userId:string,shopId:string,roles?:string[]){const m=await env.DB.prepare('SELECT role FROM shop_staff WHERE shop_id=? AND user_id=? AND is_active=1').bind(shopId,userId).first<{role:string}>();if(!m||roles&&!roles.includes(m.role))throw new ApiError(403,'FORBIDDEN','You do not have permission for this shop');return m}
async function rateLimit(env:Env,key:string,limit:number,windowSeconds:number){const w=Math.floor(now()/windowSeconds)*windowSeconds;await env.DB.prepare(`INSERT INTO auth_rate_limits(key,window_start,count) VALUES(?,?,1) ON CONFLICT(key,window_start) DO UPDATE SET count=count+1`).bind(key,w).run();const r=await env.DB.prepare('SELECT count FROM auth_rate_limits WHERE key=? AND window_start=?').bind(key,w).first<{count:number}>();if((r?.count??0)>limit)throw new ApiError(429,'RATE_LIMITED','Try again later')}
function pin(v:unknown){const p=String(v??'');if(!/^(?:\d{4}|\d{6})$/.test(p))throw new ApiError(400,'INVALID_PIN_FORMAT','PIN must contain exactly 4 or 6 digits');return p}
function b64(bytes:Uint8Array){let x='';for(const v of bytes)x+=String.fromCharCode(v);return btoa(x)}
function unb64(s:string){return Uint8Array.from(atob(s),c=>c.charCodeAt(0))}
async function derivePin(pinValue:string,salt:Uint8Array,pepper:string,iterations:number){const material=await crypto.subtle.importKey('raw',enc.encode(`${pinValue}:${pepper}`),'PBKDF2',false,['deriveBits']);const bits=await crypto.subtle.deriveBits({name:'PBKDF2',hash:'SHA-256',salt:salt.buffer as ArrayBuffer,iterations},material,256);return b64(new Uint8Array(bits))}
function safeEqual(a:string,b:string){if(a.length!==b.length)return false;let d=0;for(let i=0;i<a.length;i++)d|=a.charCodeAt(i)^b.charCodeAt(i);return d===0}
function distanceM(lat1:number,lng1:number,lat2:number,lng2:number){const R=6371000,rad=(d:number)=>d*Math.PI/180,dLat=rad(lat2-lat1),dLng=rad(lng2-lng1);const a=Math.sin(dLat/2)**2+Math.cos(rad(lat1))*Math.cos(rad(lat2))*Math.sin(dLng/2)**2;return 2*R*Math.asin(Math.min(1,Math.sqrt(a)))}
const orderTransitions:Record<string,string[]>={PENDING:['ACCEPTED','REJECTED','CANCELLED'],ACCEPTED:['PACKING','CANCELLED'],PACKING:['READY','CANCELLED'],READY:['OUT_FOR_DELIVERY','DELIVERED'],OUT_FOR_DELIVERY:['DELIVERED'],DELIVERED:[],REJECTED:[],CANCELLED:[]};
async function issueSession(env:Env,userId:string,device?:string){const access=`ld_a_${id()}${id()}`,refresh=`ld_r_${id()}${id()}`,t=now(),sid=id();await env.DB.prepare('INSERT INTO sessions(id,user_id,access_hash,refresh_hash,access_expires_at,refresh_expires_at,device_name,created_at,last_used_at) VALUES(?,?,?,?,?,?,?,?,?)').bind(sid,userId,await hash(access),await hash(refresh),t+Number(env.ACCESS_TTL_SECONDS||900),t+Number(env.REFRESH_TTL_SECONDS||2592000),device?.slice(0,100)??null,t,t).run();return{accessToken:access,refreshToken:refresh,accessExpiresAt:t+Number(env.ACCESS_TTL_SECONDS||900)}}
async function register(req:Request,env:Env){const b=await body(req),p=phone(b.phone),secret=pin(b.pin),confirm=pin(b.confirmPin);if(secret!==confirm)throw new ApiError(400,'PIN_MISMATCH','PIN confirmation does not match');const ip=req.headers.get('cf-connecting-ip')??'unknown';await rateLimit(env,`register-ip:${await hash(ip)}`,10,3600);const existing=await env.DB.prepare('SELECT id FROM users WHERE phone_e164=?').bind(p).first();if(existing)throw new ApiError(409,'MOBILE_ALREADY_REGISTERED','Mobile number is already registered');const salt=crypto.getRandomValues(new Uint8Array(16)),iterations=pinIterations(env),uid=id(),t=now(),customer=b.role==='CUSTOMER'?1:0,shopkeeper=b.role==='SHOPKEEPER'?1:0;if(!customer&&!shopkeeper)throw new ApiError(400,'INVALID_ROLE','Choose CUSTOMER or SHOPKEEPER');const pinHash=await derivePin(secret,salt,env.PIN_PEPPER,iterations);await env.DB.batch([env.DB.prepare('INSERT INTO users(id,phone_e164,pin_hash,pin_salt,pin_iterations,created_at,updated_at) VALUES(?,?,?,?,?,?,?)').bind(uid,p,pinHash,b64(salt),iterations,t,t),env.DB.prepare('INSERT INTO profiles(user_id,is_customer,is_shopkeeper,updated_at) VALUES(?,?,?,?)').bind(uid,customer,shopkeeper,t)]);return json({userId:uid,...await issueSession(env,uid,typeof b.deviceName==='string'?b.deviceName:undefined)},201)}
async function login(req:Request,env:Env){const b=await body(req),p=phone(b.phone),secret=pin(b.pin),ip=req.headers.get('cf-connecting-ip')??'unknown';await rateLimit(env,`login-ip:${await hash(ip)}`,40,900);const u=await env.DB.prepare('SELECT id,pin_hash,pin_salt,pin_iterations,status,failed_login_count,locked_until FROM users WHERE phone_e164=?').bind(p).first<any>();const t=now();if(u?.locked_until&&u.locked_until>t)throw new ApiError(429,'ACCOUNT_TEMPORARILY_LOCKED',`Try again after ${u.locked_until}`);let candidate:string|null=null;try{candidate=u?await derivePin(secret,unb64(u.pin_salt),env.PIN_PEPPER,u.pin_iterations):await derivePin(secret,new Uint8Array(16),env.PIN_PEPPER,pinIterations(env))}catch{candidate=null}if(!u||u.status!=='ACTIVE'||!candidate||!safeEqual(candidate,u.pin_hash)){if(u){const failures=u.failed_login_count+1,locked=failures>=5?t+Math.min(3600,300*Math.pow(2,Math.floor((failures-5)/2))):null;await env.DB.prepare('UPDATE users SET failed_login_count=?,locked_until=?,updated_at=? WHERE id=?').bind(failures,locked,t,u.id).run()}throw new ApiError(401,'INVALID_CREDENTIALS','Mobile number or PIN is incorrect')}await env.DB.prepare('UPDATE users SET failed_login_count=0,locked_until=NULL,updated_at=? WHERE id=?').bind(t,u.id).run();return json({userId:u.id,...await issueSession(env,u.id,typeof b.deviceName==='string'?b.deviceName:undefined)})}
async function refresh(req:Request,env:Env){const b=await body(req),r=str(b.refreshToken,'refreshToken',20,200),h=await hash(r),t=now();const s=await env.DB.prepare(`SELECT s.id,s.user_id FROM sessions s JOIN users u ON u.id=s.user_id WHERE refresh_hash=? AND revoked_at IS NULL AND refresh_expires_at>? AND u.status='ACTIVE'`).bind(h,t).first<any>();if(!s)throw new ApiError(401,'INVALID_REFRESH','Refresh token invalid');const changed=await env.DB.prepare('UPDATE sessions SET revoked_at=? WHERE id=? AND revoked_at IS NULL').bind(t,s.id).run();if(!changed.meta.changes)throw new ApiError(401,'INVALID_REFRESH','Refresh token invalid');return json(await issueSession(env,s.user_id))}
async function profile(req:Request,env:Env,a:Auth){if(req.method==='GET'){const p=await env.DB.prepare('SELECT user_id,display_name,preferred_language,is_customer,is_shopkeeper,version FROM profiles WHERE user_id=?').bind(a.userId).first();return json(p)}const b=await body(req),name=str(b.displayName,'displayName',1,100),lang=b.preferredLanguage==='hi'?'hi':'en',customer=b.isCustomer===true?1:0,shopkeeper=b.isShopkeeper===true?1:0,t=now();await env.DB.prepare('UPDATE profiles SET display_name=?,preferred_language=?,is_customer=MAX(is_customer,?),is_shopkeeper=MAX(is_shopkeeper,?),version=version+1,updated_at=? WHERE user_id=?').bind(name,lang,customer,shopkeeper,t,a.userId).run();if(customer)await env.DB.prepare(`INSERT INTO customers(id,user_id,name,mobile_e164,created_at,updated_at) SELECT ?,u.id,?,u.phone_e164,?,? FROM users u WHERE u.id=? ON CONFLICT(user_id) DO UPDATE SET name=excluded.name,updated_at=excluded.updated_at`).bind(id(),name,t,t,a.userId).run();return profile(new Request(req.url),env,a)}
async function createShop(req:Request,env:Env,a:Auth){const b=await body(req),mutation=str(b.mutationId,'mutationId',36,36),requestHash=await hash(JSON.stringify(b));const old=await env.DB.prepare('SELECT response_json,request_hash FROM sync_operations WHERE user_id=? AND mutation_id=?').bind(a.userId,mutation).first<any>();if(old){if(old.request_hash!==requestHash)throw new ApiError(409,'IDEMPOTENCY_MISMATCH','Mutation ID was already used');return json(JSON.parse(old.response_json),200)}const priorOwner=await env.DB.prepare(`SELECT s.id shop_id FROM shop_staff ss JOIN shops s ON s.id=ss.shop_id WHERE ss.user_id=? AND ss.role='OWNER' AND ss.is_active=1 LIMIT 1`).bind(a.userId).first<{shop_id:string}>();if(priorOwner)throw new ApiError(409,'SHOP_ALREADY_EXISTS','You already own a shop; each account can own only one shop');const sid=id(),sub=id(),t=now(),lat=Number(b.latitude),lng=Number(b.longitude);if(!Number.isFinite(lat)||lat < -90||lat>90||!Number.isFinite(lng)||lng < -180||lng>180)throw new ApiError(400,'VALIDATION_ERROR','Invalid location');const pincode=str(b.pincode,'pincode',6,6);if(!/^[1-9]\d{5}$/.test(pincode))throw new ApiError(400,'VALIDATION_ERROR','Invalid pincode');const out={id:sid,status:'ACTIVE',subscription:{status:'TRIAL',trialEndsAt:t+2592000}};const statements=[env.DB.prepare(`INSERT INTO shops(id,name,owner_name,address_line,locality,city,pincode,category,latitude,longitude,description,opens_at,closes_at,status,is_published,accepts_online_orders,public_slug,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,'ACTIVE',1,1,?,?,?)`).bind(sid,str(b.name,'name',2,120),str(b.ownerName,'ownerName',2,100),str(b.addressLine,'addressLine',3,300),str(b.locality,'locality',2,100),str(b.city,'city',2,100),pincode,str(b.category,'category',2,80),lat,lng,typeof b.description==='string'?b.description.slice(0,500):null,typeof b.opensAt==='string'?b.opensAt:null,typeof b.closesAt==='string'?b.closesAt:null,`shop-${sid.replaceAll('-','').slice(0,16)}`,t,t),env.DB.prepare('INSERT INTO shop_staff(shop_id,user_id,role,created_at) VALUES(?,?,?,?)').bind(sid,a.userId,'OWNER',t),env.DB.prepare('INSERT INTO shop_delivery_settings(shop_id,updated_at) VALUES(?,?)').bind(sid,t),env.DB.prepare(`INSERT INTO subscriptions(id,shop_id,status,trial_started_at,trial_ends_at,created_at,updated_at) VALUES(?,?, 'TRIAL',?,?,?,?)`).bind(sub,sid,t,t+2592000,t,t),env.DB.prepare('UPDATE profiles SET is_shopkeeper=1,version=version+1,updated_at=? WHERE user_id=?').bind(t,a.userId),env.DB.prepare('INSERT INTO sync_operations(user_id,mutation_id,operation,shop_id,request_hash,response_json,created_at) VALUES(?,?,?,?,?,?,?)').bind(a.userId,mutation,'CREATE_SHOP',sid,requestHash,JSON.stringify(out),t)];try{await env.DB.batch(statements)}catch(e){const replay=await env.DB.prepare('SELECT response_json FROM sync_operations WHERE user_id=? AND mutation_id=?').bind(a.userId,mutation).first<{response_json:string}>();if(replay?.response_json)return json(JSON.parse(replay.response_json),200);throw new ApiError(409,'SHOP_ALREADY_EXISTS','You already own a shop; each account can own only one shop')}return json(out,201)}
async function myShops(env:Env,a:Auth){const r=await env.DB.prepare(`SELECT s.id,s.name,s.status,s.city,s.locality,s.is_published,s.public_slug,s.version,s.owner_name,s.phone_e164,s.address_line,s.pincode,s.description,ss.role,sub.status subscription_status,sub.trial_ends_at FROM shops s JOIN shop_staff ss ON ss.shop_id=s.id LEFT JOIN subscriptions sub ON sub.shop_id=s.id WHERE ss.user_id=? AND ss.is_active=1 ORDER BY s.created_at`).bind(a.userId).all();return json({items:r.results})}
async function privateShop(env:Env,a:Auth,shopId:string){await membership(env,a.userId,shopId);const s=await env.DB.prepare(`SELECT s.*,d.delivery_enabled,d.radius_m,d.minimum_order_paise,d.delivery_fee_paise,d.free_delivery_threshold_paise,d.estimated_minutes FROM shops s JOIN shop_delivery_settings d ON d.shop_id=s.id WHERE s.id=?`).bind(shopId).first();if(!s)throw new ApiError(404,'NOT_FOUND','Shop not found');return json(s)}
function uuid(v:unknown,name='id'){const x=String(v??'');if(!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(x))throw new ApiError(400,'VALIDATION_ERROR',`Invalid ${name}`);return x}
function int(v:unknown,name:string,min=0,max=2_000_000_000){if(typeof v!=='number'||!Number.isSafeInteger(v)||v<min||v>max)throw new ApiError(400,'VALIDATION_ERROR',`Invalid ${name}`);return v}
function optional(v:unknown,max:number){if(v==null||v==='')return null;if(typeof v!=='string'||v.trim().length>max)throw new ApiError(400,'VALIDATION_ERROR','Invalid optional text');return v.trim()}
function barcode(v:unknown){if(v==null||v==='')return null;const x=String(v).replace(/[\s-]/g,'').toUpperCase();if(!/^[0-9A-Z]{6,32}$/.test(x))throw new ApiError(400,'INVALID_BARCODE','Barcode must contain 6–32 letters or digits');return x}
// ---- Global catalogue lookups (grocery, household and cosmetic packs) ----
// The same pack can reach us written several ways: zero padding never changes a GS1 check digit,
// so the printed symbol, a shop catalogue and the open databases may each hold a different length.
function uniqueCodes(args:unknown[]):string[]{
 const out:string[]=[];
 for(const raw of args){if(typeof raw!=='string')continue;const d=raw.replace(/\D/g,'');if(!d||d.length<6||d.length>14)continue;const forms=[d];if(d.length===14)forms.push(d.slice(1));else if(d.length===13){if(d[0]==='0')forms.push(d.slice(1));forms.push('0'+d)}else if(d.length===12)forms.push('0'+d,'00'+d);for(const f of forms)if(f&&f.length<=14&&!out.includes(f))out.push(f)}
 return out.slice(0,8)
}
// India-first: in.openfoodfacts.org carries far more kirana SKUs than the world instance, and the
// beauty / products instances cover cosmetics and household packs that the food instance ignores.
const OFF_HOSTS=['https://in.openfoodfacts.org','https://world.openfoodfacts.org','https://world.openbeautyfacts.org','https://world.openproductsfacts.org'];
function offText(product:any,key:string):string|null{const v=product?.[key];return typeof v==='string'&&v.trim()?v.trim():null}
function offName(product:any):string|null{
 for(const key of ['product_name','product_name_en','generic_name','generic_name_en']){const name=offText(product,key);if(name&&!/^[\d\s.,-]+$/.test(name))return name}
 return null
}
function offBrand(product:any):string|null{
 const direct=offText(product,'brands');if(direct){const first=direct.split(',')[0]?.trim();if(first)return first}
 const tags=product?.brands_tags;if(Array.isArray(tags)&&typeof tags[0]==='string'){const t=tags[0].split(':').pop()?.replace(/-/g,' ').trim();if(t)return t.replace(/\b\w/g,c=>c.toUpperCase())}
 return null
}
function offUnit(quantity:unknown):string{
 const q=String(quantity??'').toLowerCase();
 if(/\d\s*(kg|kilo)/.test(q))return 'kg';
 if(/\d\s*(g|gm|gram|grams)\b/.test(q))return 'gm';
 if(/\d\s*(l|lt|ltr|litre|liter)\b/.test(q))return 'litre';
 if(/\d\s*ml\b/.test(q))return 'ml';
 return 'piece'
}
async function receipt(env:Env,a:Auth,mutation:string,requestHash:string){const old=await env.DB.prepare('SELECT response_json,request_hash FROM sync_operations WHERE user_id=? AND mutation_id=?').bind(a.userId,mutation).first<any>();if(old&&old.request_hash!==requestHash)throw new ApiError(409,'IDEMPOTENCY_MISMATCH','Mutation ID was already used');return old?.response_json?JSON.parse(old.response_json):null}
function productSelect(where:string){return `SELECT sp.id shop_product_id,sp.shop_id,sp.product_id,p.barcode,p.name,p.brand,p.unit,p.description,sp.selling_price_paise,sp.stock_quantity_milli,sp.reserved_quantity_milli,sp.minimum_stock_milli,sp.is_available,sp.is_archived,sp.image_key,sp.image_mime_type,sp.image_size_bytes,sp.version,sp.updated_at,CASE WHEN sp.stock_quantity_milli<=sp.minimum_stock_milli THEN 1 ELSE 0 END is_low_stock FROM shop_products sp JOIN products p ON p.id=sp.product_id WHERE ${where}`}
async function listProducts(req:Request,env:Env,a:Auth,shopId:string){await membership(env,a.userId,shopId);const u=new URL(req.url),q=(u.searchParams.get('q')??'').trim(),includeArchived=u.searchParams.get('includeArchived')==='true';const r=await env.DB.prepare(productSelect(`sp.shop_id=? AND (?=1 OR sp.is_archived=0) AND (?='' OR p.name LIKE ? OR COALESCE(p.brand,'') LIKE ? OR COALESCE(p.barcode,'') LIKE ?) ORDER BY p.name LIMIT 200`)).bind(shopId,includeArchived?1:0,q,`%${q}%`,`%${q}%`,`%${q}%`).all();return json({items:r.results})}
async function getProduct(env:Env,a:Auth,shopId:string,shopProductId:string){await membership(env,a.userId,shopId);const x=await env.DB.prepare(productSelect('sp.shop_id=? AND sp.id=?')).bind(shopId,shopProductId).first();if(!x)throw new ApiError(404,'NOT_FOUND','Product not found');return json(x)}
async function createProduct(req:Request,env:Env,a:Auth,shopId:string){await membership(env,a.userId,shopId,['OWNER','MANAGER','STAFF']);const b=await body(req),mutation=uuid(b.mutationId,'mutationId'),requestHash=await hash(JSON.stringify(b)),prior=await receipt(env,a,mutation,requestHash);if(prior)return json(prior);let name=str(b.name,'name',1,160),brand=optional(b.brand,100),code=barcode(b.barcode),unit=str(b.unit,'unit',1,40),description=optional(b.description,1000);const price=int(b.sellingPricePaise,'sellingPricePaise'),opening=int(b.openingStockMilli,'openingStockMilli'),minimum=int(b.minimumStockMilli,'minimumStockMilli'),available=b.isAvailable===false?0:1,t=now();let productId=typeof b.productId==='string'?uuid(b.productId,'productId'):null;if(productId){if(!await env.DB.prepare('SELECT id FROM products WHERE id=?').bind(productId).first())throw new ApiError(404,'GLOBAL_PRODUCT_NOT_FOUND','Global product not found')}else if(code){productId=(await env.DB.prepare('SELECT id FROM products WHERE barcode=?').bind(code).first<{id:string}>())?.id??null}if(productId){const canonical=await env.DB.prepare('SELECT name,brand,barcode,unit,description FROM products WHERE id=?').bind(productId).first<any>();name=canonical.name;brand=canonical.brand;code=canonical.barcode;unit=canonical.unit;description=canonical.description}if(productId&&await env.DB.prepare('SELECT id FROM shop_products WHERE shop_id=? AND product_id=?').bind(shopId,productId).first())throw new ApiError(409,'SHOP_PRODUCT_EXISTS','This product is already attached to the shop');let globalImageKey:string|null=null,globalImageMime:string|null=null,globalImageSize:number|null=null;if(productId&&env.MEDIA&&code){try{const gk=`global-products/${code}/front.jpg`;const head=await env.MEDIA.head(gk);if(head){globalImageKey=gk;globalImageMime=(head.httpMetadata?.contentType as string)??'image/jpeg';globalImageSize=head.size}}catch{}}const globalId=productId??id(),shopProductId=id(),inventoryId=id();const result={shopProductId,shopId,productId:globalId,name,brand,barcode:code,unit,description,sellingPricePaise:price,stockQuantityMilli:opening,reservedQuantityMilli:0,minimumStockMilli:minimum,isAvailable:available===1,isArchived:false,version:1,inventoryTransactionId:opening>0?inventoryId:null};const statements:D1PreparedStatement[]=[];if(!productId)statements.push(env.DB.prepare('INSERT INTO products(id,barcode,name,brand,unit,description,created_by_user_id,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?)').bind(globalId,code,name,brand,unit,description,a.userId,t,t));statements.push(env.DB.prepare('INSERT INTO shop_products(id,shop_id,product_id,selling_price_paise,stock_quantity_milli,minimum_stock_milli,is_available,image_key,image_mime_type,image_size_bytes,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)').bind(shopProductId,shopId,globalId,price,opening,minimum,available,globalImageKey,globalImageMime,globalImageSize,t,t));if(opening>0)statements.push(env.DB.prepare(`INSERT INTO inventory_transactions(id,shop_id,shop_product_id,type,quantity_delta_milli,stock_after_milli,mutation_id,actor_user_id,created_at) VALUES(?,?,?,'OPENING_STOCK',?,?,?,?,?)`).bind(inventoryId,shopId,shopProductId,opening,opening,mutation,a.userId,t));statements.push(env.DB.prepare('INSERT INTO sync_operations(user_id,mutation_id,operation,shop_id,request_hash,response_json,created_at) VALUES(?,?,?,?,?,?,?)').bind(a.userId,mutation,'CREATE_PRODUCT',shopId,requestHash,JSON.stringify(result),t));try{await env.DB.batch(statements)}catch(e){throw new ApiError(409,'PRODUCT_CONFLICT','Barcode or shop product already exists')}return json(result,201)}
async function updateProduct(req:Request,env:Env,a:Auth,shopId:string,shopProductId:string){await membership(env,a.userId,shopId,['OWNER','MANAGER']);const b=await body(req),mutation=uuid(b.mutationId,'mutationId'),requestHash=await hash(JSON.stringify(b)),prior=await receipt(env,a,mutation,requestHash);if(prior)return json(prior);const current=await env.DB.prepare(`SELECT sp.*,p.name,p.brand,p.barcode,p.unit,p.description,p.created_by_user_id,(SELECT count(*) FROM shop_products x WHERE x.product_id=sp.product_id) attachment_count FROM shop_products sp JOIN products p ON p.id=sp.product_id WHERE sp.id=? AND sp.shop_id=?`).bind(shopProductId,shopId).first<any>();if(!current)throw new ApiError(404,'NOT_FOUND','Product not found');const version=int(b.version,'version',1),price=int(b.sellingPricePaise,'sellingPricePaise'),minimum=int(b.minimumStockMilli,'minimumStockMilli'),available=b.isAvailable===false?0:1,name=str(b.name,'name',1,160),brand=optional(b.brand,100),code=barcode(b.barcode),unit=str(b.unit,'unit',1,40),description=optional(b.description,1000);if(current.version!==version)throw new ApiError(409,'VERSION_CONFLICT','Product has changed; refresh before editing');const globalChanged=name!==current.name||brand!==current.brand||code!==current.barcode||unit!==current.unit||description!==current.description;if(globalChanged&&(current.created_by_user_id!==a.userId||current.attachment_count>1))throw new ApiError(403,'GLOBAL_PRODUCT_LOCKED','Shared global product identity cannot be edited');if(code&&await env.DB.prepare('SELECT id FROM products WHERE barcode=? AND id<>?').bind(code,current.product_id).first())throw new ApiError(409,'BARCODE_EXISTS','Barcode already exists');const t=now(),result={shopProductId,shopId,productId:current.product_id,name,brand,barcode:code,unit,description,sellingPricePaise:price,stockQuantityMilli:current.stock_quantity_milli,reservedQuantityMilli:current.reserved_quantity_milli,minimumStockMilli:minimum,isAvailable:available===1,isArchived:current.is_archived===1,version:version+1};const statements=[env.DB.prepare('UPDATE shop_products SET selling_price_paise=?,minimum_stock_milli=?,is_available=?,version=version+1,updated_at=? WHERE id=? AND shop_id=? AND version=?').bind(price,minimum,available,t,shopProductId,shopId,version)];if(globalChanged)statements.push(env.DB.prepare('UPDATE products SET barcode=?,name=?,brand=?,unit=?,description=?,version=version+1,updated_at=? WHERE id=?').bind(code,name,brand,unit,description,t,current.product_id));statements.push(env.DB.prepare('INSERT INTO sync_operations(user_id,mutation_id,operation,shop_id,request_hash,response_json,created_at) VALUES(?,?,?,?,?,?,?)').bind(a.userId,mutation,'UPDATE_PRODUCT',shopId,requestHash,JSON.stringify(result),t));await env.DB.batch(statements);return json(result)}
