async function fetchGlobalProduct(env:Env,code:string,userId:string){const hosts=OFF_HOSTS;const deadline=Date.now()+20000;for(const host of hosts)for(const candidate of uniqueCodes([code])){if(Date.now()>deadline)return null;try{const res=await fetch(`${host}/api/v2/product/${encodeURIComponent(candidate)}.json?fields=product_name,product_name_en,generic_name,generic_name_en,brands,brands_tags,quantity,image_front_small_url,image_url`,{headers:{'user-agent':'LocalDukaan/1.0 (support@localdukaan.in)'},signal:AbortSignal.timeout(6000)});if(!res.ok)continue;const data=await res.json() as any;if(data.status!==1||!data.product)continue;const name=offName(data.product);if(!name)continue;const brand=offBrand(data.product);const unit=offUnit(data.product.quantity);const pid=id(),t=now();let imageB64:string|null=null;const url=typeof data.product.image_front_small_url==='string'?data.product.image_front_small_url:(typeof data.product.image_url==='string'?data.product.image_url:null);if(url&&url.startsWith('https://')&&env.MEDIA){try{const ir=await fetch(url,{signal:AbortSignal.timeout(6000)});if(ir.ok){const buf=await ir.arrayBuffer();if(buf.byteLength>0&&buf.byteLength<=2_000_000){const bytes=new Uint8Array(buf);imageB64=b64(bytes)}}}catch{}}await env.DB.prepare('INSERT INTO products(id,barcode,name,brand,unit,description,remote_image_url,created_by_user_id,created_at,updated_at) VALUES(?,?,?,?,?,NULL,?,?,?,?,?)').bind(pid,code,name.slice(0,160),brand,unit,url,userId,t,t).run();return{id:pid,barcode:code,name:name.slice(0,160),brand,unit,description:null,version:1,imageB64,imageUrl:url}}catch{}}if(Date.now()>deadline)return null;try{const key=env.UPCITEMDB_KEY;const u=key?`https://api.upcitemdb.com/prod/lookup?user_key=${encodeURIComponent(key)}&upc=${encodeURIComponent(code)}`:`https://search.upcitemdb.com/api/trial/lookup?upc=${encodeURIComponent(code)}`;const hr=await fetch(u,{headers:{'accept':'application/json','user-agent':'LocalDukaan/1.0 (support@localdukaan.in)'},signal:AbortSignal.timeout(8000)});if(hr.ok){const hd=await hr.json() as any;if(hd?.code==='OK'&&Array.isArray(hd.items)&&hd.items.length>0){const it=hd.items[0];const nm=String(it.title??'').trim();if(nm){const nb=String(it.brand??'').trim()||null;const npid=id(),nt=now();await env.DB.prepare('INSERT INTO products(id,barcode,name,brand,unit,description,remote_image_url,created_by_user_id,created_at,updated_at) VALUES(?,?,?,?,?,NULL,?,?,?,?)').bind(npid,code,nm.slice(0,160),nb,'piece',null,userId,nt,nt).run();return{id:npid,barcode:code,name:nm.slice(0,160),brand:nb,unit:'piece',description:null,version:1,imageB64:null,imageUrl:null}}}}}catch{}return null}
async function globalProductImage(env:Env,code:string){if(env.MEDIA){try{const o=await env.MEDIA.get(`global-products/${code}/front.jpg`);if(o)return new Response(o.body,{headers:{'content-type':String(o.httpMetadata?.contentType??'image/jpeg'),'cache-control':'public, max-age=86400'}})}catch{}}let url:string|null=null;try{const row=await env.DB.prepare('SELECT remote_image_url FROM products WHERE barcode=?').bind(code).first<{remote_image_url:string|null}>();if(row?.remote_image_url)url=row.remote_image_url}catch{}if(!url){const hosts=OFF_HOSTS;for(const host of hosts){try{const pr=await fetch(`${host}/api/v2/product/${encodeURIComponent(code)}.json?fields=image_front_small_url`,{headers:{'user-agent':'LocalDukaan/1.0 (support@localdukaan.in)'},signal:AbortSignal.timeout(6000)});if(!pr.ok)continue;const data=await pr.json() as any;const u=typeof data?.product?.image_front_small_url==='string'?data.product.image_front_small_url:null;if(u){url=u;break}}catch{}}}if(!url)throw new ApiError(404,'IMAGE_NOT_FOUND','No image');let abuf:ArrayBuffer|null=null,mime='image/jpeg';try{const ir=await fetch(url,{headers:{'user-agent':'LocalDukaan/1.0 (support@localdukaan.in)'},signal:AbortSignal.timeout(15000)});if(ir.ok){const b2=await ir.arrayBuffer();if(b2.byteLength>0&&b2.byteLength<=2_000_000){abuf=b2;mime=ir.headers.get('content-type')??'image/jpeg'}}}catch{}if(!abuf)throw new ApiError(404,'IMAGE_NOT_FOUND','No image');if(env.MEDIA){try{await env.MEDIA.put(`global-products/${code}/front.jpg`,abuf,{httpMetadata:{contentType:mime}})}catch{}}try{await env.DB.prepare('UPDATE products SET remote_image_url=? WHERE barcode=? AND remote_image_url IS NULL').bind(url,code).run()}catch{}return new Response(abuf,{headers:{'content-type':mime,'cache-control':'public, max-age=86400'}})}
async function lookupBarcode(req:Request,env:Env,a:Auth){void a;const b=await body(req),code=barcode(b.barcode);if(!code)throw new ApiError(400,'INVALID_BARCODE','Barcode is required');const wanted=uniqueCodes([code,...(Array.isArray(b.candidates)?b.candidates:[])]);for(const candidate of wanted){const p=await env.DB.prepare('SELECT id,barcode,name,brand,unit,description,version,remote_image_url FROM products WHERE barcode=?').bind(candidate).first<any>();if(p)return json({found:true,product:p,imageUrl:p.remote_image_url??null})}if(env.ENVIRONMENT==='test')return json({found:false,barcode:code});const g=await fetchGlobalProduct(env,code,a.userId);if(!g)return json({found:false,barcode:code});return json({found:true,product:{id:g.id,barcode:g.barcode,name:g.name,brand:g.brand,unit:g.unit,description:g.description,version:g.version},imageUrl:g.imageUrl??null,imageBase64:g.imageB64})}
async function updateShopProfile(req:Request,env:Env,a:Auth,shopId:string){await membership(env,a.userId,shopId,['OWNER','MANAGER']);const b=await body(req),mutation=uuid(b.mutationId,'mutationId'),requestHash=await hash(JSON.stringify(b)),prior=await receipt(env,a,mutation,requestHash);if(prior)return json(prior);const version=int(b.version,'version',1),current=await env.DB.prepare('SELECT version,public_slug FROM shops WHERE id=?').bind(shopId).first<any>();if(!current)throw new ApiError(404,'NOT_FOUND','Shop not found');if(current.version!==version)throw new ApiError(409,'VERSION_CONFLICT','Shop has changed; refresh before editing');const pincode=str(b.pincode,'pincode',6,6);if(!/^[1-9]\d{5}$/.test(pincode))throw new ApiError(400,'VALIDATION_ERROR','Invalid pincode');const t=now(),slug=current.public_slug??`shop-${shopId.replaceAll('-','').slice(0,16)}`,result={id:shopId,name:str(b.name,'name',2,120),ownerName:str(b.ownerName,'ownerName',2,100),phone:optional(b.phone,20),addressLine:str(b.addressLine,'addressLine',3,300),locality:str(b.locality,'locality',2,100),city:str(b.city,'city',2,100),pincode,description:optional(b.description,500),isPublished:b.isPublished===true,publicSlug:slug,version:version+1};await env.DB.batch([env.DB.prepare('UPDATE shops SET name=?,owner_name=?,phone_e164=?,address_line=?,locality=?,city=?,pincode=?,description=?,is_published=?,public_slug=?,version=version+1,updated_at=? WHERE id=? AND version=?').bind(result.name,result.ownerName,result.phone,result.addressLine,result.locality,result.city,result.pincode,result.description,result.isPublished?1:0,slug,t,shopId,version),env.DB.prepare('INSERT INTO sync_operations(user_id,mutation_id,operation,shop_id,request_hash,response_json,created_at) VALUES(?,?,?,?,?,?,?)').bind(a.userId,mutation,'UPDATE_SHOP_PROFILE',shopId,requestHash,JSON.stringify(result),t)]);return json(result)}
async function uploadProductImage(req:Request,env:Env,a:Auth,shopId:string,shopProductId:string){await membership(env,a.userId,shopId,['OWNER','MANAGER','STAFF']);if(!env.MEDIA)throw new ApiError(503,'MEDIA_UNAVAILABLE','Media storage is not configured');const mutation=uuid(req.headers.get('idempotency-key'),'Idempotency-Key'),mime=(req.headers.get('content-type')??'').toLowerCase();if(!['image/jpeg','image/png','image/webp'].includes(mime))throw new ApiError(415,'INVALID_IMAGE_TYPE','Only JPEG, PNG, or WebP is allowed');const bytes=await req.arrayBuffer();if(bytes.byteLength<1||bytes.byteLength>5*1024*1024)throw new ApiError(413,'INVALID_IMAGE_SIZE','Image must be between 1 byte and 5 MB');const sp=await env.DB.prepare('SELECT id,image_key,version FROM shop_products WHERE id=? AND shop_id=? AND is_archived=0').bind(shopProductId,shopId).first<{id:string,image_key:string|null,version:number}>();if(!sp)throw new ApiError(404,'NOT_FOUND','Product not found');const requestHash=await hash(`${shopId}:${shopProductId}:${mime}:${bytes.byteLength}:${await hash(String.fromCharCode(...new Uint8Array(bytes.slice(0,Math.min(bytes.byteLength,4096)))))}`),prior=await receipt(env,a,mutation,requestHash);if(prior)return json(prior);const ext=mime==='image/jpeg'?'jpg':mime==='image/png'?'png':'webp',key=`shops/${shopId}/products/${shopProductId}/${mutation}.${ext}`;await env.MEDIA.put(key,bytes,{httpMetadata:{contentType:mime},customMetadata:{shopId,shopProductId}});const result={shopProductId,imageKey:key,mimeType:mime,sizeBytes:bytes.byteLength,version:sp.version+1},t=now();await env.DB.batch([env.DB.prepare('UPDATE shop_products SET image_key=?,image_mime_type=?,image_size_bytes=?,version=version+1,updated_at=? WHERE id=? AND shop_id=?').bind(key,mime,bytes.byteLength,t,shopProductId,shopId),env.DB.prepare('INSERT INTO sync_operations(user_id,mutation_id,operation,shop_id,request_hash,response_json,created_at) VALUES(?,?,?,?,?,?,?)').bind(a.userId,mutation,'PRODUCT_IMAGE',shopId,requestHash,JSON.stringify(result),t)]);if(sp.image_key&&sp.image_key!==key)await env.MEDIA.delete(sp.image_key).catch(()=>{});return json(result,201)}
async function getProductImage(env:Env,a:Auth,shopId:string,shopProductId:string){await membership(env,a.userId,shopId);if(!env.MEDIA)throw new ApiError(503,'MEDIA_UNAVAILABLE','Media storage is not configured');const sp=await env.DB.prepare('SELECT image_key,image_mime_type FROM shop_products WHERE id=? AND shop_id=? AND is_archived=0').bind(shopProductId,shopId).first<{image_key:string|null,image_mime_type:string|null}>();if(!sp)throw new ApiError(404,'NOT_FOUND','Product not found');if(!sp.image_key)throw new ApiError(404,'IMAGE_NOT_FOUND','Product has no image');const object=await env.MEDIA.get(sp.image_key);if(!object)throw new ApiError(404,'IMAGE_NOT_FOUND','Image object not found');return new Response(object.body,{headers:{'content-type':sp.image_mime_type??'application/octet-stream','cache-control':'private, max-age=300'}})}
