function optionalPhone(v:unknown){if(v==null||v==='')return null;return phone(v)}
function customerSelect(where:string){return `SELECT sc.id shop_customer_id,sc.shop_id,sc.customer_id,COALESCE(sc.display_name_override,c.name) display_name,sc.normalized_phone,sc.notes,sc.credit_enabled,sc.credit_limit_paise,sc.current_balance_paise,CASE WHEN sc.credit_enabled=1 AND sc.credit_limit_paise IS NOT NULL THEN MAX(0,sc.credit_limit_paise-sc.current_balance_paise) ELSE NULL END available_credit_paise,sc.is_archived,sc.version,sc.updated_at FROM shop_customers sc JOIN customers c ON c.id=sc.customer_id WHERE ${where}`}
async function listCustomers(req:Request,env:Env,a:Auth,shopId:string){await membership(env,a.userId,shopId);const u=new URL(req.url),q=(u.searchParams.get('q')??'').trim(),limit=Math.min(100,Math.max(1,Number(u.searchParams.get('limit')??50)||50)),offset=Math.max(0,Number(u.searchParams.get('offset')??0)||0),due=u.searchParams.get('due');const r=await env.DB.prepare(customerSelect(`sc.shop_id=? AND sc.is_archived=0 AND (?='' OR COALESCE(sc.display_name_override,c.name) LIKE ? OR COALESCE(sc.normalized_phone,'') LIKE ?) AND (?='' OR (?='due' AND sc.current_balance_paise>0) OR (?='clear' AND sc.current_balance_paise=0)) ORDER BY COALESCE(sc.display_name_override,c.name),sc.id LIMIT ? OFFSET ?`)).bind(shopId,q,`%${q}%`,`%${q}%`,due??'',due??'',due??'',limit,offset).all();return json({items:r.results,nextOffset:r.results.length===limit?offset+limit:null})}
