async function changePin(req:Request,env:Env,a:Auth){const b=await body(req),current=pin(b.currentPin),next=pin(b.newPin),confirm=pin(b.confirmPin);if(next!==confirm)throw new ApiError(400,'PIN_MISMATCH','PIN confirmation does not match');if(next===current)throw new ApiError(400,'PIN_UNCHANGED','New PIN must be different from the current PIN');const u=await env.DB.prepare(`SELECT pin_hash,pin_salt,pin_iterations FROM users WHERE id=? AND status='ACTIVE'`).bind(a.userId).first<any>();if(!u)throw new ApiError(401,'INVALID_SESSION','Session expired or invalid');const candidate=await derivePin(current,unb64(u.pin_salt),env.PIN_PEPPER,u.pin_iterations).catch(()=>null);if(!candidate||!safeEqual(candidate,u.pin_hash))throw new ApiError(401,'INVALID_PIN','Current PIN is incorrect');const salt=crypto.getRandomValues(new Uint8Array(16)),t=now(),iters=pinIterations(env),newHash=await derivePin(next,salt,env.PIN_PEPPER,iters);await env.DB.batch([env.DB.prepare('UPDATE users SET pin_hash=?,pin_salt=?,pin_iterations=?,failed_login_count=0,locked_until=NULL,updated_at=? WHERE id=?').bind(newHash,b64(salt),iters,t,a.userId),env.DB.prepare('UPDATE sessions SET revoked_at=? WHERE user_id=? AND id!=? AND revoked_at IS NULL').bind(t,a.userId,a.sessionId)]);return json({changed:true})}
function adminOk(req:Request,env:Env){const t=env.ADMIN_TOKEN;if(!t)throw new ApiError(503,'ADMIN_UNCONFIGURED','Admin token is not configured');if(req.headers.get('x-admin-token')!==t&&new URL(req.url).searchParams.get('token')!==t)throw new ApiError(401,'ADMIN_UNAUTHORIZED','Invalid admin token')}
async function adminShops(env:Env){const rows=(await env.DB.prepare(`SELECT s.id,s.name,s.status,s.is_published,s.accepts_online_orders,s.city,s.locality,s.created_at,u.phone_e164 owner_phone,p.display_name owner_name FROM shops s LEFT JOIN shop_staff ss ON ss.shop_id=s.id AND ss.role='OWNER' LEFT JOIN users u ON u.id=ss.user_id LEFT JOIN profiles p ON p.user_id=ss.user_id ORDER BY s.created_at DESC LIMIT 200`).all()).results;const counts=(await env.DB.prepare('SELECT shop_id,count(*) products FROM shop_products GROUP BY shop_id').all()).results;const byShop=new Map(counts.map((c:any)=>[c.shop_id,c.products]));return json({items:rows.map((r:any)=>({...r,product_count:byShop.get(r.id)??0}))})}
async function adminSetShop(env:Env,shopId:string,req:Request){const b=await body(req);const status=typeof b.status==='string'?String(b.status).toUpperCase():null;if(status&&!['DRAFT','PENDING_APPROVAL','ACTIVE','SUSPENDED','CLOSED'].includes(status))throw new ApiError(400,'VALIDATION_ERROR','Invalid status');const pub=b.publish==null?null:(b.publish===true?1:0);const r=await env.DB.prepare('UPDATE shops SET status=COALESCE(?,status),is_published=COALESCE(?,is_published),updated_at=? WHERE id=?').bind(status,pub,now(),shopId).run();if(!r.meta.changes)throw new ApiError(404,'NOT_FOUND','Shop not found');const s=await env.DB.prepare('SELECT id,name,status,is_published FROM shops WHERE id=?').bind(shopId).first();return json(s)}
function adminPage(env:Env,req:Request){const token=new URL(req.url).searchParams.get('token')??'';const html=`<!doctype html><html lang="hi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>LocalDukaan Admin</title><style>
body{font-family:system-ui;background:#F6FAF7;margin:0;padding:16px}h1{color:#15803D}
table{width:100%;border-collapse:collapse;background:#fff;border-radius:12px;overflow:hidden}
th,td{padding:10px;text-align:left;border-bottom:1px solid #E4EFE8;font-size:14px}
th{background:#EFF7F1;color:#15803D}.live{color:#15803D;font-weight:700}.off{color:#B45309;font-weight:700}
button{padding:6px 10px;border:0;border-radius:8px;cursor:pointer;font-weight:600;margin:2px}
.pub{background:#16A34A;color:#fff}.unpub{background:#F59E0B;color:#fff}.sus{background:#DC2626;color:#fff}.act{background:#2563EB;color:#fff}
</style></head><body><h1>🏪 LocalDukaan Admin</h1><p>Shop par Live/Pause/Suspend ka control. <a id="rl" href="#">Refresh</a></p><div id="out">Loading…</div>
<script>
'use strict';
var T=${JSON.stringify(token)};
var rl=document.getElementById('rl');if(rl)rl.href=window.location.href;
function el(tag,cls,text){var e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined&&text!==null)e.textContent=String(text);return e}
async function act(id,body){try{var r=await fetch('/v1/admin/shops/'+encodeURIComponent(id),{method:'POST',headers:{'x-admin-token':T,'content-type':'application/json'},body:JSON.stringify(body)});if(!r.ok){var d=await r.json().catch(function(){return{}});alert((d.error&&d.error.message)?d.error.message:('Error '+r.status))}}catch(e){alert(String(e))}load()}
async function load(){var out=document.getElementById('out');try{var r=await fetch('/v1/admin/shops',{headers:{'x-admin-token':T}});if(!r.ok){var d=await r.json().catch(function(){return{}});out.textContent=(d.error&&d.error.message)?d.error.message:('Error '+r.status);return}var data=await r.json();out.textContent='';var t=el('table');var head=el('tr');['Shop','Owner','City','Products','Status','Actions'].forEach(function(x){head.appendChild(el('th',null,x))});t.appendChild(head);
data.items.forEach(function(s){var tr=el('tr');
tr.appendChild(el('td',null,s.name));
tr.appendChild(el('td',null,((s.owner_name||'')+' '+(s.owner_phone||'')).trim()));
tr.appendChild(el('td',null,s.city));
tr.appendChild(el('td',null,s.product_count));
var st=el('td',s.is_published?'live':'off',(s.is_published?'LIVE':'NOT LIVE')+' / '+s.status);tr.appendChild(st);
var td=el('td');
var b1=el('button',s.is_published?'unpub':'pub',s.is_published?'Pause':'Live karo');b1.onclick=function(){act(s.id,{publish:!s.is_published})};td.appendChild(b1);
var b2=el('button',s.status==='SUSPENDED'?'act':'sus',s.status==='SUSPENDED'?'Un-suspend':'Suspend');b2.onclick=function(){act(s.id,{status:s.status==='SUSPENDED'?'ACTIVE':'SUSPENDED'})};td.appendChild(b2);
tr.appendChild(td);t.appendChild(tr)});
out.appendChild(t)}catch(e){out.textContent='Network error: '+String(e)}}
load();setInterval(load,15000);
</script></body></html>`;return new Response(html,{headers:{'content-type':'text/html; charset=utf-8','cache-control':'no-store'}})}
export default {async fetch(req:Request,env:Env):Promise<Response>{try{const u=new URL(req.url),p=u.pathname;if(req.method==='GET'&&(p==='/admin'||p==='/admin/')){adminOk(req,env);return adminPage(env,req)}if(p.startsWith('/v1/admin/')){adminOk(req,env);if(p==='/v1/admin/shops'&&req.method==='GET')return await adminShops(env);const ms=p.match(/^\/v1\/admin\/shops\/([^/]+)$/);if(ms&&req.method==='POST')return await adminSetShop(env,decodeURIComponent(ms[1]),req);throw new ApiError(404,'NOT_FOUND','Admin endpoint not found')}if(req.method==='GET'&&p==='/health')return json({ok:true});if(req.method==='POST'&&p==='/v1/auth/register')return await register(req,env);if(req.method==='POST'&&p==='/v1/auth/login')return await login(req,env);if(req.method==='POST'&&p==='/v1/auth/refresh')return await refresh(req,env);const gimg=p.match(/^\/v1\/global-products\/([^/]+)\/image$/);if(gimg&&req.method==='GET')return await globalProductImage(env,decodeURIComponent(gimg[1]));const a=await bearer(req,env);if(p==='/v1/profile'&&(req.method==='GET'||req.method==='PUT'))return await profile(req,env,a);if(p==='/v1/shops'&&req.method==='POST')return await createShop(req,env,a);if(p==='/v1/shops/mine'&&req.method==='GET')return await myShops(env,a);if(p==='/v1/products/barcode/lookup'&&req.method==='POST')return await lookupBarcode(req,env,a);const collection=p.match(/^\/v1\/shops\/([^/]+)\/products$/);if(collection&&req.method==='GET')return await listProducts(req,env,a,collection[1]);if(collection&&req.method==='POST')return await createProduct(req,env,a,collection[1]);const item=p.match(/^\/v1\/shops\/([^/]+)\/products\/([^/]+)$/);if(item&&req.method==='GET')return await getProduct(env,a,item[1],item[2]);if(item&&req.method==='PUT')return await updateProduct(req,env,a,item[1],item[2]);if(item&&req.method==='DELETE')return await archiveProduct(req,env,a,item[1],item[2]);const image=p.match(/^\/v1\/shops\/([^/]+)\/products\/([^/]+)\/image$/);if(image&&req.method==='GET')return await getProductImage(env,a,image[1],image[2]);if(image&&req.method==='POST')return await uploadProductImage(req,env,a,image[1],image[2]);if(image&&req.method==='DELETE')return await removeProductImage(req,env,a,image[1],image[2]);const customer=p.match(/^\/v1\/shops\/([^/]+)\/customers(?:\/([^/]+))?(?:\/(statement|credit|payment|adjustment))?$/);if(customer&&req.method==='GET'&&!customer[2])return await listCustomers(req,env,a,customer[1]);if(customer&&req.method==='POST'&&!customer[2])return await createCustomer(req,env,a,customer[1]);if(customer&&req.method==='GET'&&customer[2]&&!customer[3])return await getCustomer(env,a,customer[1],customer[2]);if(customer&&req.method==='PUT'&&customer[2]&&!customer[3])return await updateCustomer(req,env,a,customer[1],customer[2]);if(customer&&req.method==='DELETE'&&customer[2]&&!customer[3])return await archiveCustomer(req,env,a,customer[1],customer[2]);if(customer&&req.method==='GET'&&customer[3]==='statement')return await statement(req,env,a,customer[1],customer[2]);if(customer&&req.method==='POST'&&['credit','payment','adjustment'].includes(customer[3]??''))return await mutateCredit(req,env,a,customer[1],customer[2],customer[3]!);const stock=p.match(/^\/v1\/shops\/([^/]+)\/products\/([^/]+)\/(stock-in|stock-out)$/);if(stock&&req.method==='POST')return await mutateStock(req,env,a,stock[1],stock[2],stock[3]==='stock-in'?'IN':'OUT');const inventory=p.match(/^\/v1\/shops\/([^/]+)\/products\/([^/]+)\/inventory$/);if(inventory&&req.method==='GET')return await inventoryHistory(req,env,a,inventory[1],inventory[2]);const sales=p.match(/^\/v1\/shops\/([^/]+)\/sales(?:\/([^/]+))?$/);if(sales&&req.method==='POST'&&!sales[2])return await createSale(req,env,a,sales[1]);if(sales&&req.method==='GET')return await listSales(req,env,a,sales[1],sales[2]);const low=p.match(/^\/v1\/shops\/([^/]+)\/low-stock$/);if(low&&req.method==='GET')return await lowStock(env,a,low[1]);const purchase=p.match(/^\/v1\/shops\/([^/]+)\/purchase-list(?:\/([^/]+))?$/);if(purchase&&req.method==='GET'&&!purchase[2])return await listPurchaseItems(env,a,purchase[1]);if(purchase&&req.method==='POST'&&!purchase[2])return await addPurchaseItem(req,env,a,purchase[1]);if(purchase&&req.method==='PUT'&&purchase[2])return await updatePurchaseItem(req,env,a,purchase[1],purchase[2]);if(purchase&&req.method==='DELETE'&&purchase[2])return await deletePurchaseItem(req,env,a,purchase[1],purchase[2]);const shopProfile=p.match(/^\/v1\/shops\/([^/]+)\/profile$/);if(shopProfile&&req.method==='GET')return await privateShop(env,a,shopProfile[1]);if(shopProfile&&req.method==='PUT')return await updateShopProfile(req,env,a,shopProfile[1]);const m=p.match(/^\/v1\/shops\/([^/]+)\/private$/);if(m&&req.method==='GET')return await privateShop(env,a,m[1]);if(p==='/v1/auth/logout'&&req.method==='POST')return await logout(req,env,a);if(p==='/v1/auth/change-pin'&&req.method==='POST')return await changePin(req,env,a);if(p==='/v1/addresses'&&req.method==='POST')return await createAddress(req,env,a);if(p==='/v1/addresses'&&req.method==='GET')return await listAddresses(env,a);if(p==='/v1/my/credit'&&req.method==='GET')return await myCredit(env,a);if(p==='/v1/market/shops'&&req.method==='GET')return await marketShops(req,env,a);const mkt=p.match(/^\/v1\/market\/shops\/([^/]+)$/);if(mkt&&req.method==='GET')return await marketShopPage(env,decodeURIComponent(mkt[1]));if(p==='/v1/orders'&&req.method==='POST')return await createOrder(req,env,a);if(p==='/v1/orders'&&req.method==='GET')return await listOrders(env,a);const ord=p.match(/^\/v1\/orders\/([^/]+)(?:\/(cancel))?$/);if(ord&&req.method==='GET'&&!ord[2])return await getOrder(env,a,ord[1]);if(ord&&req.method==='POST'&&ord[2]==='cancel')return await cancelOrder(req,env,a,ord[1]);const so=p.match(/^\/v1\/shops\/([^/]+)\/orders(?:\/([^/]+))?(?:\/(status))?$/);if(so&&req.method==='GET'&&!so[2])return await shopOrders(req,env,a,so[1]);if(so&&req.method==='POST'&&so[2]&&so[3]==='status')return await updateOrderStatus(req,env,a,so[1],so[2]);throw new ApiError(404,'NOT_FOUND','Endpoint not found')}catch(e){const x=e instanceof ApiError?e:new ApiError(500,'INTERNAL_ERROR','Unexpected server error');return json({error:{code:x.code,message:x.message}},x.status)}}};
